const R:&str="/home/ubuntu/src/zopro-perf-work/coarse-proof-phase-entry176";const OUT:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-11-06-coarse-proof-phase-entry-preflight176";
fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn walk(p:&Path)->Vec<PathBuf>{let mut v=vec![];for e in fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){v.extend(walk(&p));}else{v.push(p);}}v.sort();v}
fn gzip(p:&Path,v:&Value){let b=serde_json::to_vec(v).unwrap();let temp=p.with_extension("tmp");fs::write(&temp,&b).unwrap();assert!(Command::new("gzip").args(["-n","-c"]).arg(&temp).stdout(Stdio::from(fs::File::create(p).unwrap())).status().unwrap().success());let result=Command::new("gzip").args(["-d","-c"]).arg(p).output().unwrap();assert!(result.status.success());assert_eq!(result.stdout,b);fs::remove_file(temp).unwrap();}
fn hex_entry(b:&[u8])->Value{let hex=b.iter().map(|b|format!("{b:02x}")).collect::<String>();let recovered=hex.as_bytes().chunks_exact(2).map(|b|u8::from_str_radix(std::str::from_utf8(b).unwrap(),16).unwrap()).collect::<Vec<_>>();assert_eq!(recovered,b);json!({"hex":hex,"length":b.len(),"sha256":hash(b)})}
